import {readiness} from './aml.mjs';
export const CATEGORIES=['Missing evidence','Unsupported conclusion','Interpretation error','Incomplete scope','Narrative inconsistency'];
const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;
export function snapshot(c,n){const {qc,...notes}=n;return canonical(structuredClone({scope:{seed:c.manifest.seed,from_block:c.manifest.from_block,to_block:c.manifest.to_block,...(c.review_scope||{coverage:c.coverage||'',queried_addresses:c.queried_addresses||[]})},events:c.events.map(e=>({...e,timestamp:new Date(e.timestamp).toISOString()})),notes}))}
export function changed(round,c,n){return JSON.stringify(round.snapshot)!==JSON.stringify(snapshot(c,n))}
export function submit(history,c,n,analyst){if(!analyst.trim())throw Error('Enter the analyst name or reference.');const gaps=readiness(n);if(gaps.length)throw Error('Complete the documentation checklist before submitting: '+gaps.join(', '));if(history.at(-1)?.status==='Submitted for QC')throw Error('Finish or return the current review before resubmitting.');if(history.length>=20)throw Error('This case supports up to 20 review rounds.');return [...structuredClone(history),{version:history.length+1,submitted_at:new Date().toISOString(),analyst:analyst.trim(),snapshot:snapshot(c,n),status:'Submitted for QC',findings:[],reviewer:'',decision_reason:'',decided_at:''}]}
export function addFinding(round,category,reference,comment){if(round.status!=='Submitted for QC')throw Error('Findings can only be added to an open review.');if(!CATEGORIES.includes(category)||!comment.trim())throw Error('Choose a category and enter a finding.');if(reference!=='conclusion'&&!round.snapshot.events.some(e=>e.id===reference))throw Error('Choose evidence from this submission.');if(round.findings.length>=100)throw Error('Maximum 100 findings per round.');round.findings.push({category,reference,comment:comment.trim(),response:''})}
export function decide(round,status,reviewer,reason){if(round.status!=='Submitted for QC')throw Error('This review already has an outcome.');if(!['Returned for correction','QC completed'].includes(status)||!reviewer.trim()||!reason.trim())throw Error('Enter a reviewer name and decision rationale.');if(status==='QC completed'&&round.findings.some(f=>!f.response.trim()))throw Error('Respond to every finding before completing QC, or return this submission for correction.');round.status=status;round.reviewer=reviewer.trim();round.decision_reason=reason.trim();round.decided_at=new Date().toISOString()}
export function validateHistory(value){if(value===undefined)return [];if(!Array.isArray(value)||value.length>20)throw Error('Invalid QC history.');const text=v=>typeof v==='string'&&v.length<=20000;for(const [i,r]of value.entries()){if(!r||r.version!==i+1||!['Submitted for QC','Returned for correction','QC completed'].includes(r.status)||!text(r.analyst)||!r.analyst.trim()||!Number.isFinite(Date.parse(r.submitted_at))||!r.snapshot?.scope||!Array.isArray(r.snapshot.events)||r.snapshot.events.length>1000||!r.snapshot.notes||r.snapshot.notes.qc!==undefined||!Array.isArray(r.findings)||r.findings.length>100||!text(r.reviewer)||!text(r.decision_reason)||!text(r.decided_at))throw Error('Malformed QC submission.');if(r.status==='Submitted for QC'&&i!==value.length-1)throw Error('Only the latest QC round may be open.');if(r.status!=='Submitted for QC'&&(!r.reviewer.trim()||!r.decision_reason.trim()||!Number.isFinite(Date.parse(r.decided_at))))throw Error('QC outcome is missing its reviewer, date or rationale.');for(const f of r.findings){if(!CATEGORIES.includes(f.category)||!text(f.comment)||!f.comment.trim()||!text(f.response)||(f.reference!=='conclusion'&&!r.snapshot.events.some(e=>e.id===f.reference)))throw Error('Invalid QC finding or evidence reference.')}if(r.status==='QC completed'&&r.findings.some(f=>!f.response.trim()))throw Error('Completed QC has unanswered findings.')}return structuredClone(value)}
export function qcReport(history){return '\n\n## QC review history\n\nSelf-reported names and file-based history; identities and independence are not verified. Outcomes apply only to the attached submitted version.\n'+history.map(r=>`\n### Submission ${r.version}: ${r.status}\nAnalyst: ${r.analyst}\nSubmitted: ${r.submitted_at}\nReviewer: ${r.reviewer||'Pending'}\nDecision: ${r.decision_reason||'Pending'}\nDecision time: ${r.decided_at||'Pending'}\n`+r.findings.map(f=>`\n* ${f.category} / ${f.reference}: ${f.comment}\n  Analyst response: ${f.response||'Not yet provided'}\n`).join('')).join('')}
